# -*- coding: utf-8 -*-
# Generated by Antigravity & qwen3-coder:30b per AGENT.md
"""cam_studio.cam.generator — Единый генератор высококачественного G-кода для деревообработки."""

import math
import time
from .chipload import calculate_feeds_speeds
from .helical import generate_helical_entry
from .tabs3d import apply_3d_tabs
from .grain import generate_grain_toolpaths


class CamStudioGenerator:
    def __init__(self, settings: dict):
        self.settings = settings
        self.gcode = []
        self.toolpaths = []  # Для 3D WebGL визуализации
        self.warnings = []

    def build(self) -> dict:
        st = self.settings
        stock = st.get('stock', {'width': 300, 'height': 200, 'thickness': 22, 'material': 'walnut'})
        tool = st.get('tool', {'dia': 6.35, 'flutes': 2, 'rpm': 18000, 'stepdown': 3.5})
        grain_angle = float(st.get('grain_angle', 0.0))
        pocket_depth = float(st.get('pocket_depth', 12.0))
        dish_radius = float(st.get('dish_radius', 6.35))
        climb_only = bool(st.get('climb_only', True))
        z_safe = float(st.get('z_safe', 9.0))
        use_3d_tabs = bool(st.get('use_3d_tabs', True))

        # 1. Расчет режимов резания
        cf = calculate_feeds_speeds(
            tool_dia_mm=tool['dia'],
            flutes=tool['flutes'],
            material=stock['material'],
            target_rpm=tool['rpm'],
            cut_depth_mm=tool.get('stepdown', 3.5)
        )
        if cf['burn_risk']:
            self.warnings.append("Внимание: Риск прижога волокон при текущем соотношении подачи и оборотов!")

        feed_cut = cf['feed_mm_min']
        feed_plunge = feed_cut * 0.4
        feed_ramp = feed_cut * 0.65

        # 2. Шапка G-кода (Masso G3 Touch + Makita RT0701C)
        lines = [
            f"% ( Generated by CamStudio Next-Gen Wood CAM )",
            f"( Date: {time.strftime('%Y-%m-%d %H:%M:%S')} )",
            f"( Stock: {stock['width']} x {stock['height']} x {stock['thickness']} mm [{stock['material']}] )",
            f"( Grain Angle: {grain_angle}° | Mode: {'Climb Milling' if climb_only else 'ZigZag'} )",
            f"( Chip Load: {cf['chip_load_mm_tooth']} mm/tooth | Feed: {feed_cut} mm/min )",
            f"( MSG: ПРОВЕРЬТЕ ШПИНДЕЛЬ Makita RT0701C ДИСК ~{cf['makita_dial']} ({cf['rpm']} RPM) )",
            f"G21 ( Metric mm )",
            f"G90 ( Absolute Coordinates )",
            f"G0 Z{z_safe:.3f}",
            f"M03 S{cf['rpm']}",
            f"G4 P3.0 ( Ждем набора оборотов фрезером 3 сек )",
            f"G0 Z{z_safe:.3f}"
        ]

        # 3. Карман (Pocketing): Helical Entry + Grain-Aware Toolpaths
        # Базовый прямоугольный карман со скругленными углами
        margin = 15.0
        p_min_x, p_max_x = margin, stock['width'] - margin
        p_min_y, p_max_y = margin, stock['height'] - margin
        cx = (p_min_x + p_max_x) / 2.0
        cy = (p_min_y + p_max_y) / 2.0

        lines.append(f"\n( === OPERATION 1: Pocket Clearing & Grain-Aware Finishing === )")
        
        # Helical Ramp врезание по центру
        stepdown = tool['stepdown']
        current_depth = 0.0
        pass_idx = 1
        stepover = tool['dia'] * 0.45

        while current_depth < pocket_depth:
            next_depth = min(pocket_depth, current_depth + stepdown)
            lines.append(f"\n( --- Pocket Pass {pass_idx}: Z=-{next_depth:.3f} mm --- )")
            
            # Спиральный вход в центр
            helix_lines = generate_helical_entry(
                center_x=cx, center_y=cy,
                start_z=-current_depth, target_z=-next_depth,
                helix_radius=tool['dia'] * 0.7,
                pitch_per_turn=1.0,
                feed_ramp=feed_ramp
            )
            lines.extend(helix_lines)

            # Выборка вдоль волокон
            grain_passes = generate_grain_toolpaths(
                bbox=(p_min_x + tool['dia']/2, p_min_y + tool['dia']/2, p_max_x - tool['dia']/2, p_max_y - tool['dia']/2),
                grain_angle_deg=grain_angle,
                stepover_mm=stepover,
                climb_only=climb_only
            )

            for gpass in grain_passes:
                p0, p1 = gpass[0], gpass[1]
                # Безопасный переход
                lines.append(f"G0 Z{-next_depth + 1.0:.3f}")
                lines.append(f"G0 X{p0[0]:.3f} Y{p0[1]:.3f}")
                lines.append(f"G1 Z{-next_depth:.3f} F{feed_plunge:.1f}")
                lines.append(f"G1 X{p1[0]:.3f} Y{p1[1]:.3f} F{feed_cut:.1f}")
                self.toolpaths.append({
                    'type': 'cut',
                    'points': [(p0[0], p0[1], -next_depth), (p1[0], p1[1], -next_depth)]
                })

            current_depth = next_depth
            pass_idx += 1

        # Отвод на безопасную высоту
        lines.append(f"G0 Z{z_safe:.3f}")

        # 4. Наружный контур (Outer Contour) с плавными 3D мостиками
        lines.append(f"\n( === OPERATION 2: Outer Profile with 3D Triangular Tabs === )")
        w, h = stock['width'], stock['height']
        r_offset = tool['dia'] / 2.0
        
        # Наружный прямоугольник с запасом
        outline_pts = [
            (-r_offset, -r_offset),
            (w + r_offset, -r_offset),
            (w + r_offset, h + r_offset),
            (-r_offset, h + r_offset),
            (-r_offset, -r_offset)
        ]

        # Финальный проход по контуру на полную глубину с 3D мостиками
        z_final = -stock['thickness'] - 0.2  # Небольшой перебор 0.2мм для чистого прореза
        tab_h = 3.5
        tab_w = 14.0

        if use_3d_tabs:
            points_3d = apply_3d_tabs(outline_pts[:-1], z_bottom=z_final, tab_height=tab_h, tab_width=tab_w, num_tabs=4)
            # Замыкаем
            if points_3d:
                points_3d.append(points_3d[0])

            lines.append(f"G0 X{points_3d[0][0]:.3f} Y{points_3d[0][1]:.3f}")
            lines.append(f"G1 Z{points_3d[0][2]:.3f} F{feed_plunge:.1f}")
            
            for pt in points_3d[1:]:
                lines.append(f"G1 X{pt[0]:.3f} Y{pt[1]:.3f} Z{pt[2]:.3f} F{feed_cut:.1f}")

            self.toolpaths.append({
                'type': 'profile_3d_tabs',
                'points': points_3d
            })
        else:
            # Обычный контур
            lines.append(f"G0 X{outline_pts[0][0]:.3f} Y{outline_pts[0][1]:.3f}")
            lines.append(f"G1 Z{z_final:.3f} F{feed_plunge:.1f}")
            for pt in outline_pts[1:]:
                lines.append(f"G1 X{pt[0]:.3f} Y{pt[1]:.3f} F{feed_cut:.1f}")

        # 5. Хвост программы
        lines.extend([
            f"\n( === Program End === )",
            f"G0 Z{z_safe:.3f}",
            f"M05 ( Spindle Off )",
            f"G0 X0.000 Y0.000 ( Return Home )",
            f"M30 ( Program Stop & Rewind )",
            f"%"
        ])

        return {
            'gcode': "\n".join(lines),
            'line_count': len(lines),
            'toolpaths': self.toolpaths,
            'feeds_speeds': cf,
            'warnings': self.warnings,
            'stock': stock
        }
